def can_chain(dominoes):
    """Return a list of dominoes forming a closed chain, or None if impossible.

    A closed chain is an ordering of all given dominoes (each may be flipped)
    such that the touching ends of adjacent dominoes match, and the free end
    of the last domino matches the free end of the first domino.
    """
    if not dominoes:
        return []

    def backtrack(remaining, chain, current_end):
        if not remaining:
            if chain[0][0] == current_end:
                return chain
            return None
        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            if a == current_end:
                result = backtrack(rest, chain + [(a, b)], b)
                if result is not None:
                    return result
            if b == current_end and a != b:
                result = backtrack(rest, chain + [(b, a)], a)
                if result is not None:
                    return result
        return None

    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        result = backtrack(rest, [(a, b)], b)
        if result is not None:
            return result
        if a != b:
            result = backtrack(rest, [(b, a)], a)
            if result is not None:
                return result
    return None
